window.NOTES={"version":43,"chapters":[{"number":1,"title":"信息技术与计算机文化","summary":"计算机发展、信息表示、硬件、软件与计算机系统的基础概念。","sections":[{"id":"1.1","title":"信息与信息技术"},{"id":"1.2","title":"计算机技术概论"},{"id":"1.3","title":"计算机中信息的表示"},{"id":"1.4","title":"计算机系统"},{"id":"1.5","title":"微型计算机系统"}]},{"number":2,"title":"Windows 10 操作系统","summary":"操作系统特征、Windows界面、文件管理、系统设置与维护。","sections":[{"id":"2.1","title":"操作系统概述"},{"id":"2.2","title":"Windows 10 基础"},{"id":"2.3","title":"文件和文件夹管理"},{"id":"2.4","title":"控制面板"},{"id":"2.5","title":"Windows 10 的系统维护"},{"id":"2.6","title":"Windows 10 的实用工具"}]},{"number":3,"title":"字处理软件 Word 2016","summary":"文档编辑、格式排版、表格、图文混排与长文档功能。","sections":[{"id":"3.1","title":"使用 Office 2016 应用程序"},{"id":"3.2","title":"Word 2016 的基本操作"},{"id":"3.3","title":"文档格式化与排版"},{"id":"3.4","title":"表格制作"},{"id":"3.5","title":"图文混排"},{"id":"3.6","title":"文档的保护与打印"},{"id":"3.7","title":"Word 2016 的高级应用"}]},{"number":4,"title":"电子表格系统 Excel 2016","summary":"工作表操作、公式与函数、格式化、数据处理和图表。","sections":[{"id":"4.1","title":"Excel 2016 概述"},{"id":"4.2","title":"Excel 2016 的基本操作"},{"id":"4.3","title":"Excel 公式与函数"},{"id":"4.4","title":"格式化工作表"},{"id":"4.5","title":"数据处理"},{"id":"4.6","title":"使用图表"}]},{"number":5,"title":"演示文稿软件 PowerPoint 2016","summary":"幻灯片组织、外观、动画、切换与放映设置。","sections":[{"id":"5.1","title":"PowerPoint 2016 基础"},{"id":"5.2","title":"幻灯片页面设计"},{"id":"5.3","title":"幻灯片页面外观的修饰"},{"id":"5.4","title":"动画效果和动作设置"},{"id":"5.5","title":"播放和打印演示文稿"},{"id":"5.6","title":"演示文稿的其他功能"}]},{"number":6,"title":"计算机网络及网页制作","summary":"网络结构、Internet应用、HTML、网页与信息检索。","sections":[{"id":"6.1","title":"计算机网络概述"},{"id":"6.2","title":"计算机网络系统"},{"id":"6.3","title":"Internet 基础和应用"},{"id":"6.4","title":"网页、网页制作及 HTML 简介"},{"id":"6.5","title":"信息检索"}]},{"number":7,"title":"数字多媒体技术基础","summary":"多媒体特征、媒体元素、图像格式、颜色和视频。","sections":[{"id":"7.1","title":"数字多媒体技术概述"},{"id":"7.2","title":"数字多媒体系统组成及常用软件"},{"id":"7.3","title":"常用多媒体制作软件"}]},{"number":8,"title":"信息安全","summary":"安全属性、恶意软件、防火墙、密码技术和信息伦理。","sections":[{"id":"8.1","title":"信息安全概述"},{"id":"8.2","title":"计算机病毒"},{"id":"8.3","title":"防火墙"},{"id":"8.4","title":"Windows 10 操作系统安全"},{"id":"8.5","title":"信息伦理"}]},{"number":9,"title":"信息技术前沿","summary":"虚拟现实、云计算、物联网、区块链与人工智能。","sections":[{"id":"9.1","title":"虚拟现实和增强现实"},{"id":"9.2","title":"云计算和高性能计算"},{"id":"9.3","title":"物联网技术"},{"id":"9.4","title":"大数据技术"},{"id":"9.5","title":"区块链技术"},{"id":"9.6","title":"人工智能"},{"id":"9.7","title":"量子通信"},{"id":"9.8","title":"元宇宙"}]},{"number":10,"title":"数据库技术基础","summary":"关系数据库、数据库管理系统、关系运算、SQL与NoSQL。","sections":[{"id":"10.1","title":"数据库技术基础"},{"id":"10.2","title":"数据库管理系统"},{"id":"10.3","title":"数据库设计与 NoSQL"}]},{"number":11,"title":"计算思维","summary":"计算思维、算法表示、算法特征和基本控制结构。","sections":[{"id":"11.1","title":"计算思维"},{"id":"11.2","title":"计算思维与算法"},{"id":"11.3","title":"算法的控制结构"},{"id":"11.4","title":"面向对象程序设计"},{"id":"11.5","title":"基础算法设计思想"}]}],"notes":[{"q":32,"chapter":1,"section":"1.1","type":"判断","topic":"信息与数据","title":"数据是信息的符号化表示和载体","trigger":"真题反复考查信息、数据、符号与意义之间的标准关系。","conclusion":"数据是信息的符号化表示，是信息记录、传输和处理的载体；信息是数据经过解释后表达的意义。","points":["同一数据在不同语境中可能表达不同信息。","文字、数字、图像和声音等都可编码为数据。","介质承载数据，数据承载可被解释的信息。"],"boundary":"不要把信息与数据完全等同，也不要把载体关系写反。","id":"y2025q23","sources":[{"year":2023,"q":32,"type":"判断"},{"year":2025,"q":23,"type":"多选"}],"keys":["2023-32","2025-23"]},{"q":29,"chapter":1,"section":"1.1","type":"多选","topic":"自主可控","title":"自主可控关注核心能力，也必须遵循安全规范","trigger":"真题从技术引进、国产化和数据库考查自主可控、安全与供应链。","conclusion":"自主可控要看核心技术、知识产权、供应链和维护生态；开放学习与自主创新可并行，国产化也不能跳过安全评估。","points":["关键技术应具备理解、修改和持续演进能力。","权利边界、替代能力和维护生态决定能否长期运行。","自主研发不是拒绝开放标准与国际协作。","北斗卫星导航系统是我国自主建设、独立运行的卫星导航系统，是理解自主可控的具体实例。"],"boundary":"自主可控不是只看产地标签，也不能把引进技术等同于已经掌握核心能力。","id":"y2026q18","sources":[{"year":2024,"q":29,"type":"多选"},{"year":2025,"q":15,"type":"单选"},{"year":2026,"q":18,"type":"单选"}],"keys":["2024-29","2025-15","2026-18"]},{"q":1,"chapter":1,"section":"1.2","type":"单选","topic":"计算机发展","title":"电子管、晶体管与集成电路标志主要代际","trigger":"真题从ENIAC和代表元件反复考查电子计算机代际。","conclusion":"第一代以电子管为主，第二代以晶体管为主，第三代以中小规模集成电路为主，第四代以大规模和超大规模集成电路为主。","points":["ENIAC属于早期第一代电子管计算机。","继电器主要属于机电式计算阶段。","集成度提升推动体积、功耗、可靠性和性能变化。","ENIAC采用电子管，主要使用十进制；不能把它与后来经典存储程序计算机的二进制结构混同。"],"boundary":"代际判断看主要电子元件，不以机器体积、运行速度或是否联网作为划分依据。","id":"y2025q21","sources":[{"year":2023,"q":1,"type":"单选"},{"year":2024,"q":21,"type":"多选"},{"year":2025,"q":21,"type":"多选"},{"year":2021,"q":1,"type":"单选","page":1}],"keys":["2023-1","2024-21","2025-21","2021-1"]},{"q":1,"chapter":1,"section":"1.2","type":"单选","topic":"发展趋势","title":"计算机发展不是简单的“越大越快”","trigger":"题目要求辨析计算机体积、速度、功能与应用范围的发展趋势。","conclusion":"计算机总体向高性能、微型化、网络化、智能化等方向发展，体积增大不是速度提高的必要条件。","points":["集成度提高可以在更小体积内容纳更多器件并提升性能。","大型高性能计算机与微型设备会并行发展，不能用单一尺寸概括全部计算机。","性能取决于体系结构、芯片工艺、并行能力、存储与软件等多项因素。","巨型化侧重高性能、大容量与复杂计算能力，不是单纯把机箱做大。"],"boundary":"“计算能力更强”不能直接推导为“机器体积更大”。","id":"y2026q1","sources":[{"year":2026,"q":1,"type":"单选"},{"year":2022,"q":3,"type":"单选"}],"keys":["2026-1","2022-3"]},{"q":31,"chapter":1,"section":"1.3","type":"填空","topic":"二进制运算","title":"二进制减法与借位规则","trigger":"题目要求计算二进制数1001减去111。","conclusion":"1001₂ − 111₂ = 10₂；前导0可以省略。","points":["二进制减法遵循“借一当二”：0减1时向高位借1，本位得到2再相减。","可先转成十进制校验：9−7=2，再将2写成二进制10。","结果写成010或0010数值相同，但通常省略无意义的前导0。"],"boundary":"按位计算时要把两个数右对齐；前导0不改变数值，小数点后的尾随0也通常不改变数值。","id":"y2020q31","sources":[{"year":2020,"q":31,"type":"填空"}],"keys":["2020-31"]},{"q":32,"chapter":1,"section":"1.3","type":"填空","topic":"信息表示","title":"bit、Byte、像素与存储容量单位","trigger":"三道题分别考查bit与Byte、容量换算以及数字图像的构成与存储。","conclusion":"bit表示一个二进制位，Byte表示字节，1 B=8 bit；容量计算先统一位与字节，再按题设选择1000或1024进位。","points":["SI前缀按1000进位：1 kB=1000 B，1 MB=10⁶ B，1 GB=10⁹ B，1 TB=10¹² B。","IEC前缀按1024进位：1 KiB=2¹⁰ B，1 MiB=2²⁰ B，1 GiB=2³⁰ B，1 TiB=2⁴⁰ B。","旧教材常用KB、MB表示1024进位。题目明确采用此口径时按题设计算，并在步骤中写清换算关系；跨两级需要乘或除两次进率。","像素是位图的基本图像元素。未压缩像素数据量=宽×高×每像素位数÷8，结果单位为B；24位RGB通常是红、绿、蓝各8位。","例如1024×768像素、每像素24位的图像，纯像素数据为2359296 B=2.25 MiB。bit/s是位速率，B/s是字节速率，同一前缀下数值相差8倍。"],"boundary":"图像公式计算的是题设条件下的像素数据，不一定等于图像文件大小；文件头、调色板、行填充及压缩会改变文件大小。像素不能直接作为所有图形文件的存储单位。","id":"merged-3","sources":[{"year":2020,"q":32,"type":"填空"},{"year":2025,"q":22,"type":"多选"},{"year":2026,"q":2,"type":"单选"}],"keys":["2020-32","2025-22","2026-2"]},{"q":31,"chapter":1,"section":"1.3","type":"判断","topic":"字符编码","title":"字符编码、汉字机内码、字形与全角半角要分清","trigger":"真题从ASCII、汉字机内码规则、字形码和全角半角考查字符表示。","conclusion":"字符编码解决“这是哪个字符”，字形数据解决“这个字符怎样显示”；字符占用多少字节必须结合具体编码，不能笼统认定汉字永远占两个字节。","points":["标准ASCII为7位，共128个编码，存入一个8位字节时最高位通常为0；数字、大写字母、小写字母各自连续排列，按码值比较时数字小于大写字母、大写字母小于小写字母。","ASCII中A=41H、a=61H，同一字母的大小写码值相差20H；G=47H，因此J=4AH。H表示十六进制，不参与数值运算。","区位码表示字符在编码表中的区和位，国标码用于信息交换，机内码用于内部表示；教材常见GB2312双字节汉字机内码两个字节最高位均为1，但满足此条件仍不能保证编码合法。","Unicode为字符分配码位，UTF-8和UTF-16规定具体编码形式；UTF-8编码一个Unicode标量值使用1至4字节，UTF-16使用2或4字节。全角Ａ与半角A也是不同字符，不能只看外形判断相同。","字形可用点阵或轮廓描述。单色、每点1位且不计附加信息时，16×16点阵字形占32 B，24×24占72 B；字体或字号改变会影响字形数据，不会因此改变字符身份。"],"boundary":"双字节机内码、16×16点阵和16位编码是不同概念。字符编码长度不能用点阵规模求，字形数据量也不能套用“一汉字两字节”。","id":"y2025q2","sources":[{"year":2023,"q":31,"type":"判断"},{"year":2024,"q":2,"type":"单选"},{"year":2025,"q":2,"type":"单选"},{"year":2022,"q":21,"type":"多选"},{"year":2021,"q":31,"type":"填空","page":5}],"keys":["2023-31","2024-2","2025-2","2022-21","2021-31"],"comparison":{"headers":["比较项","字符编码","字形数据"],"rows":[["回答的问题","表示哪个字符","这个字符怎样显示或打印"],["常见表示","ASCII、GB2312及Unicode的具体编码形式","点阵或轮廓"],["容量取决于","具体编码形式及字符","点阵规模、每点位数或轮廓描述"],["典型计算","标准ASCII通常存入1 B；GB2312汉字通常为2 B","16×16单色点阵：16×16÷8=32 B"],["字体改变","同一编码体系中的字符身份不因此改变","外观与字形数据可以改变"]]}},{"q":41,"chapter":1,"section":"1.3","type":"填空","topic":"进制转换","title":"整数位权、小数分组与有限表示","trigger":"真题从十进制转十六进制、整数位权、二进制分组和小数精度考查进制转换。","conclusion":"任意进制转十进制用按位权展开；十进制整数转其他进制用除基取余、逆序排列，小数部分用乘基取整、顺序排列。","points":["r进制的个位权为r⁰，向左依次为r¹、r²，向右依次为r⁻¹、r⁻²；例如10001₂=16+1=17₁₀。","十进制整数不断除以目标基数，直到商为0，再把余数倒序写出；60÷16商3余12，12对应C，所以60₁₀=3C₁₆。","小数部分不断乘以目标基数，每次取整数部分，余下小数继续乘；0.625依次乘2取得1、0、1，所以0.625₁₀=0.101₂。","二进制转八进制每3位一组，转十六进制每4位一组；以小数点为界，整数左端、小数右端补0。100010.01₂=0010 0010.0100₂=22.4₁₆，11.11₂=3.C₁₆。","有限十进制小数未必能用有限二进制精确表示；约分后分母为2的幂时才能有限表示，如0.5可以，0.1不可以。一般地，分母的质因数须全部包含在目标基数的质因数中。"],"boundary":"整数除基所得余数要逆序，小数乘基所得整数要顺序；不能跨小数点分组。3CH与0x3C都是十六进制记法，保留有限位数时还应按题设截断或舍入。","id":"y2026q41","sources":[{"year":2023,"q":41,"type":"填空"},{"year":2024,"q":31,"type":"判断"},{"year":2024,"q":42,"type":"填空"},{"year":2025,"q":41,"type":"填空"},{"year":2026,"q":41,"type":"填空"},{"year":2022,"q":42,"type":"填空"}],"keys":["2023-41","2024-31","2024-42","2025-41","2026-41","2022-42"]},{"q":21,"chapter":1,"section":"1.4","type":"多选","topic":"体系结构","title":"冯·诺依曼结构与存储程序原理","trigger":"真题从五大部件、控制器职责、二进制表示和存储程序思想反复考查经典计算机体系结构。","conclusion":"经典冯·诺依曼计算机由运算器、控制器、存储器、输入设备和输出设备组成；程序指令与数据均用二进制表示，并存放在同一存储体系中。","points":["基础组成题通常把运算器和控制器合称CPU；实际CPU还包含寄存器等部件。","运算器执行算术和逻辑运算；控制器取出指令、解释操作要求、发出控制信号并协调各部件。","“存储程序”强调先把程序指令存入存储器；“程序控制”强调机器按指令要求自动完成操作。","程序指令和数据都表现为二进制位串，不能仅看某个位串的外形判断它一定是指令或一定是数据，要结合访问与解释方式。","普通通用计算机通常把需要执行的代码从外存装入内存，由CPU反复取指、译码和执行；转移指令可以改变后续执行位置。"],"boundary":"五大部件是功能划分，不是五块独立芯片；存储程序不表示只能从第一条到最后一条直线执行，也不表示程序保存在硬盘上就已经运行。","id":"merged-1","sources":[{"year":2020,"q":21,"type":"多选"},{"year":2023,"q":42,"type":"填空"},{"year":2024,"q":22,"type":"多选"},{"year":2026,"q":22,"type":"多选"},{"year":2022,"q":1,"type":"单选"},{"year":2022,"q":31,"type":"判断"}],"keys":["2020-21","2023-42","2024-22","2026-22","2022-1","2022-31"]},{"q":23,"chapter":1,"section":"1.4","type":"多选","topic":"程序语言","title":"机器语言、汇编语言与高级语言","trigger":"题目要求从机器语言、汇编语言、C和C++中识别高级语言。","conclusion":"C和C++属于高级程序设计语言；机器语言和汇编语言属于低级语言。","points":["机器语言由机器指令代码构成，可由CPU直接识别执行。","汇编语言用助记符表达机器指令，需要汇编程序翻译。","高级语言更接近人的表达，通常通过编译、解释或混合方式运行。","机器语言直接用处理器可识别的二进制指令编码表达操作；汇编语言用助记符，但仍需汇编。"],"boundary":"“高级语言”不代表计算机可以直接执行；源程序仍需经过语言处理系统。","id":"y2020q23","sources":[{"year":2020,"q":23,"type":"多选"},{"year":2022,"q":2,"type":"单选"}],"keys":["2020-23","2022-2"]},{"q":33,"chapter":1,"section":"1.4","type":"填空","topic":"软件分类","title":"系统软件与应用软件按功能区分","trigger":"真题从软件定义、操作系统、系统自带程序和日常App反复考查软件分类。","conclusion":"软件包括程序、数据及相关文档；操作系统属于系统软件，微信、支付宝等直接服务具体任务的程序属于应用软件。","points":["系统软件管理硬件资源并为应用提供运行环境。","办公软件、通信支付App、图形工具和业务系统通常属于应用软件。","某程序随操作系统附带，不代表它必然属于系统软件。","Linux、DOS属于操作系统；Photoshop和WPS主要完成用户的具体工作，属于应用软件。"],"boundary":"“系统自带”“预装”和“系统软件”不是同义词，分类应看主要功能。","version":"按Windows 10现行口径整理","id":"merged-2","sources":[{"year":2020,"q":33,"type":"填空"},{"year":2023,"q":22,"type":"多选"},{"year":2025,"q":3,"type":"单选"},{"year":2026,"q":21,"type":"多选"},{"year":2021,"q":22,"type":"多选","page":4}],"keys":["2020-33","2023-22","2025-3","2026-21","2021-22"]},{"q":2,"chapter":1,"section":"1.4","type":"单选","topic":"计算机指令","title":"机器指令由操作码和地址码等部分组成","trigger":"真题从机器能否直接执行、操作码含义和地址信息考查指令结构。","conclusion":"机器指令是CPU可直接识别执行的操作命令，基础模型通常概括为操作码与地址码等部分；具体字段和含义由指令系统规定。","points":["操作码说明执行什么操作，如加法、传送或转移；地址码等字段提供操作数及结果位置等相关信息。","操作数可能来自寄存器、存储器，也可能是指令中直接给出的立即数，因此不能把每个操作数字段都理解成主存地址。","一条指令规定一次机器操作；程序是为完成任务组织起来的指令序列，可能包含顺序、分支和循环。","一台处理器能够识别的全部机器指令构成其指令系统；不同处理器架构的机器代码不保证能够直接互用。","机器指令可以直接执行；汇编源程序需汇编，高级语言源程序通常需编译、解释或其他语言处理过程。"],"boundary":"不要把“源程序需要翻译”扩大为“任何指令都要先编译”；也不要认为每条指令必须显式给出主存地址或下一条指令地址。","id":"y2024q41","sources":[{"year":2023,"q":2,"type":"单选"},{"year":2024,"q":41,"type":"填空"}],"keys":["2023-2","2024-41"]},{"q":1,"chapter":1,"section":"1.4","type":"单选","topic":"存储器","title":"RAM与ROM的断电特性","trigger":"真题用断电场景反复考查RAM与ROM的易失性。","conclusion":"普通RAM是可读写的运行内存，断电后内容丢失；ROM常用于保存固件，具有非易失性。读写特性、断电特性和主存外存是不同分类维度。","points":["RAM暂存正在运行的程序和数据；程序或文件保存在磁盘上，不代表其全部内容一直位于RAM中。","DRAM需要定期刷新，常用作主存；SRAM不需要这种刷新，常用作Cache。两者在普通实现中都需要持续供电保存内容。","Cache是高速缓冲存储器，用于减少CPU访问较慢主存的等待；它不是硬盘，也不是另一种永久文件保存位置。","ROM常保存固件或启动代码；EEPROM等类型可按规定方式擦写，不能把所有ROM都理解成出厂后永远无法改变。","SSD、U盘使用的Flash具有非易失性，但这些设备通常归为外存；HDD同样能断电保存数据，因此非易失存储器不等于ROM。","普通剪贴板在内存中暂存复制或剪切的数据；回收站主要在磁盘上暂存符合条件的已删除文件，二者不能混为一谈。Windows剪贴板历史记录另有固定、同步等功能，不能把普通剪贴板的断电口径无条件套用于所有历史记录。"],"boundary":"RAM中的“随机访问”不等于“随机存入”，也不应据名称推导所有RAM技术都易失；基础题未作特殊说明时，通常讨论普通易失性RAM。断电能否保留、能否改写、属于主存还是外存，要分别判断。","id":"y2026q3","sources":[{"year":2024,"q":1,"type":"单选"},{"year":2026,"q":3,"type":"单选"},{"year":2021,"q":21,"type":"多选","page":4}],"keys":["2024-1","2026-3","2021-21"],"comparison":{"headers":["名称","分类关系与典型用途","普通实现的断电特性","刷新或改写"],"rows":[["RAM","随机存取存储器；基础题通常指运行内存","普通RAM易失","可读写；是否刷新取决于类型"],["SRAM","RAM的一类；常用于Cache","易失","无需DRAM式定期刷新"],["DRAM","RAM的一类；常用于主存","易失","需要定期刷新"],["ROM","只读存储器家族；常保存固件","非易失","能否改写及方式取决于具体类型"],["Flash","闪存；常用于SSD、U盘及固件存储","非易失","可按规定方式电擦除、编程"]]}},{"q":31,"chapter":1,"section":"1.4","type":"判断","topic":"CPU与GPU","title":"GPU擅长并行计算但不能全面替代CPU","trigger":"题目判断图形处理器能否完全替代中央处理器。","conclusion":"GPU适合大量相似任务的并行运算，CPU更擅长通用控制、复杂分支和系统协调，两者通常协同工作。","points":["CPU拥有完善的控制逻辑和通用指令执行能力。","GPU通过大量计算单元提高图形和矩阵等并行任务吞吐量。","人工智能训练常依赖GPU加速，但操作系统和通用程序仍需要CPU。"],"boundary":"某些专用设备可弱化传统CPU角色，但不能据此说GPU在通用计算机中已经完全替代CPU。","id":"y2026q31","sources":[{"year":2026,"q":31,"type":"判断"}],"keys":["2026-31"]},{"q":1,"chapter":1,"section":"1.5","type":"单选","topic":"硬件识别","title":"从外形识别内存条","trigger":"题目通过硬件实物图考查CPU、内存、网卡和主板的区分。","conclusion":"图中长条形电路板、成排金手指和多颗存储芯片是内存条的典型特征。","points":["内存条安装在主板内存插槽中，承担主存储器的主要RAM功能。","CPU通常是带顶盖的方形芯片；主板是承载插槽、接口和芯片的大型电路板；网卡通常带网络接口。","识图时先看连接形式和用途，不依赖品牌标签。"],"boundary":"内存条属于主存硬件，不等同于SSD、U盘等外存；“内存”和“存储空间”在日常表达中也不能混用。","id":"y2020q1","sources":[{"year":2020,"q":1,"type":"单选"}],"keys":["2020-1"]},{"q":22,"chapter":1,"section":"1.5","type":"多选","topic":"输入设备","title":"输入、输出与存储设备的判断","trigger":"题目要求判断手写板、麦克风、投影仪和硬盘中哪些能够向计算机输入信息。","conclusion":"手写板和麦克风是典型输入设备；投影仪是输出设备；硬盘是外存，也承担双向读写。","points":["输入设备把外界信息转换成计算机可处理的数据。","输出设备把处理结果转换为人或其他设备可接收的形式。","硬盘读出数据时有输入方向、写入时有输出方向，但规范分类通常称为外存储器或输入输出设备。","触摸屏同时承担显示输出和触摸输入；扫描仪输入、音箱输出。U盘属于外部存储，读写会发生输入/输出传输，但不应简单归为仅输出设备。"],"boundary":"“有数据进入计算机”不等于教材分类中一定叫纯输入设备；磁盘、网卡和触摸屏都具有双向性。","id":"y2020q22","sources":[{"year":2020,"q":22,"type":"多选"},{"year":2022,"q":22,"type":"多选"}],"keys":["2020-22","2022-22"]},{"q":4,"target":null,"chapter":1,"section":"1.5","topic":"总线","title":"数据、地址、控制总线各司其职","conclusion":"数据总线传送内容，地址总线指定位置，控制总线传送读写等控制信号；地址宽度与数据宽度回答的是不同问题。","points":["数据总线传送指令、操作数和结果等信息；经典系统中读写需要不同传送方向。","地址总线指定要访问的存储单元或I/O位置；经典CPU作为总线主设备时，地址由CPU送出。","控制总线包含读、写、中断等信号；整组信号有不同方向，不表示每根控制线都能双向传送。","n位地址最多区分2ⁿ个地址。若按字节寻址，容量为2ⁿ B；例如20位地址可区分2²⁰个字节地址，即1 MiB。","m位并行数据总线一次可传送m位数据；地址线数不能代替数据线数。总线还可按传输方式分为串行与并行，这与按内容分类是不同维度。"],"boundary":"算可寻址容量必须先看一个地址对应多少存储量；2ⁿ首先是地址数，只有按字节寻址才能直接写成2ⁿ B。总线更宽也不能单独证明整机一定更快。","type":"单选","trigger":"从总线的判断与应用整理。","id":"y2022q4","sources":[{"year":2022,"q":4,"type":"单选"},{"year":2021,"q":32,"type":"填空","page":5}],"keys":["2022-4","2021-32"]},{"q":21,"chapter":1,"section":"1.5","type":"多选","topic":"性能指标","title":"字长、主频、核心与指令速度是不同性能指标","trigger":"真题从GHz、核心数量和处理速度等指标考查计算机性能。","conclusion":"字长描述典型处理位宽，主频描述每秒时钟周期数，核心数量描述并行执行资源；三者都不能单独代表整机实际速度。","points":["字长是处理器一次处理数据的典型二进制位数；基础题中的64位计算机通常指机器字长为64位，不是64字节。","1 GHz=10⁹ Hz，表示每秒10⁹个时钟周期；3.2 GHz表示每秒32亿个周期，不表示每秒必然执行32亿条指令。","MIPS表示每秒百万条指令，BIPS表示每秒十亿条指令；它们是指令执行速率单位，与表示容量的MB、GB不同。","多个核心可以同时处理任务，但必须有可并行的程序和合适的调度；四核3 GHz不能相加写成12 GHz。","同样主频下，不同体系结构、缓存和每周期处理能力可能带来不同速度；内存、存储设备和软件负载也会影响实际运行时间。"],"boundary":"字长、地址总线宽度和数据总线宽度不能直接视为相同；比较不同处理器时，不能只凭主频或MIPS大小作结论。","id":"y2025q1","sources":[{"year":2023,"q":21,"type":"多选"},{"year":2025,"q":1,"type":"单选"},{"year":2022,"q":32,"type":"判断"},{"year":2022,"q":41,"type":"填空"},{"year":2021,"q":2,"type":"单选","page":1}],"keys":["2023-21","2025-1","2022-32","2022-41","2021-2"],"comparison":{"headers":["指标","含义","常见误读"],"rows":[["字长","典型一次处理的二进制位数","64位不是64字节，也不等于地址线必有64根"],["主频","每秒时钟周期数；单位Hz、GHz","时钟周期数不是指令条数"],["核心数量","可并行工作的处理核心数量","四核3 GHz不能相加为12 GHz"],["MIPS、BIPS","每秒百万条、十亿条指令","不是MB、GB等存储容量单位"],["实际任务耗时","指定程序与环境下完成任务的时间","不能只由某一个硬件数字确定"]]}},{"q":31,"chapter":1,"section":"1.5","type":"判断","topic":"固态硬盘","title":"固态硬盘通常比机械硬盘读写更快","trigger":"题目比较SSD与传统机械硬盘的读写速度。","conclusion":"SSD使用闪存等电子存储介质，没有机械寻道过程，随机读写和访问延迟通常优于HDD。","points":["HDD依靠盘片旋转和磁头寻道。","SSD抗震、静音、低延迟，但价格、寿命和数据恢复特性不同。","顺序速度和实际体验还受接口、控制器与负载影响。"],"boundary":"“通常更快”不等于任何SSD在所有任务中都必然快于任何HDD。","id":"y2025q31","sources":[{"year":2025,"q":31,"type":"判断"}],"keys":["2025-31"]}],"sourceCount":460,"years":[2020,2021,2022,2023,2024,2025,2026]};
window.NOTE_REFERENCES={"y2026q18":[["北斗系统官方介绍","https://www.beidou.gov.cn/xt/"]],"merged-3":[["NIST：二进制前缀","https://physics.nist.gov/cuu/Units/binary.html"],["Microsoft：像素格式与位深","https://learn.microsoft.com/en-us/windows/win32/wic/-wic-codec-native-pixel-formats"],["Microsoft：位图文件头","https://learn.microsoft.com/en-us/windows/win32/gdi/bitmap-header-types"]],"y2025q2":[["RFC 20：ASCII原始码表","https://www.rfc-editor.org/rfc/rfc20.html"],["IBM：EUC-CN编码说明","https://www.ibm.com/docs/en/aix/7.2.0?topic=sets-euccn"],["Unicode：编码形式FAQ","https://unicode.org/faq/utf_bom.html"],["Unicode：技术介绍","https://www.unicode.org/standard/principles.html"]],"y2026q41":[["UCR：进制转换课程","https://www.cs.ucr.edu/~ehwang/courses/cs120a/00winter/binary.pdf"],["Cornell：小数乘2转换","https://www.cs.cornell.edu/courses/cs3410/2025sp/assignments/minifloat/instructions.html"],["CMU：二进制小数课程","https://www.cs.cmu.edu/afs/cs/academic/class/15213-s12/www/lectures/04-float-4up.pdf"]],"merged-1":[["Cornell：基本计算机系统","https://www.cs.cornell.edu/courses/cs316/2007fa/Lectures/Lec7_memoryProc_web.pdf"],["IBM：CPU组成","https://www.ibm.com/think/topics/central-processing-unit"],["Intel：RAM工作方式","https://www.intel.com/content/www/us/en/tech-tips-and-tricks/computer-ram.html"]],"y2024q41":[["RISC-V：官方基础指令集","https://docs.riscv.org/reference/isa/v20260120/unpriv/rv32.html"],["Cornell：机器指令及执行课程","https://www.cs.cornell.edu/courses/cs3410/2016fa/slides/05-cpu-bw.pdf"]],"y2026q3":[["Cornell：存储器与处理器","https://www.cs.cornell.edu/courses/cs316/2007fa/Lectures/Lec7_memoryProc_web.pdf"],["Micron：Flash存储技术说明","https://www.micron.com/about/blog/memory/nand/flash-forward-celebrating-40-years-of-memory-innovation"],["ST：EEPROM应用说明","https://www.st.com/resource/en/application_note/an2540-eeprom-emulation-in-str91xfxx-devices-stmicroelectronics.pdf"]],"y2022q4":[["New Mexico Tech：总线与内存课程","https://www.ee.nmt.edu/~erives/308_13/Lecture25_S13.pdf"],["USC：字节寻址与数据总线课程","https://ee.usc.edu/~redekopp/ee457/slides/EE457Unit7b_Interleaving_Notes.pdf"]],"y2025q1":[["Intel：时钟频率说明","https://www.intel.com/content/www/us/en/gaming/resources/cpu-clock-speed.html"],["Cornell：机器结构课程","https://www.cs.cornell.edu/courses/cs3410/2016fa/slides/05-cpu-bw.pdf"]]};
window.NOTE_DEMOS={"y2025q23":{"kind":"explore","title":"把数据送进解释器","task":"点击同一个“80”，观察语境如何把数据变成信息。","initial":"孤立的80只是符号化数据。","actions":[{"label":"80","stage":"数据","result":"只有符号，还不知道它描述什么。","tone":"warn"},{"label":"体重80千克","stage":"信息","result":"对象、数值和单位共同形成可理解含义。","tone":"good"},{"label":"考试成绩80分","stage":"另一条信息","result":"同一数据在不同语境中传递不同意义。","tone":"good"}]},"y2026q18":{"kind":"explore","title":"拆开“自主可控”","task":"点击四个环节，观察为什么只看“国产”两个字不够。","initial":"一套数据库能否长期自主运行，要看完整能力链。","actions":[{"label":"核心技术","stage":"核心代码与关键技术","result":"能理解、修改并持续演进关键技术，才不会被单点卡住。","tone":"good"},{"label":"知识产权","stage":"权利边界清晰","result":"合法拥有或获得充分授权，才能稳定使用、开发和分发。","tone":"good"},{"label":"供应链","stage":"关键环节可替代","result":"芯片、系统、数据库和工具链中，薄弱的一环就可能影响整体。","tone":"warn"},{"label":"维护生态","stage":"升级与迁移能力","result":"没有人才、文档、兼容和服务生态，产品也难以长期可控。","tone":"warn"}]},"y2025q21":{"kind":"explore","title":"检查ENIAC机房","task":"点击机房部件与程序设置，判断它属于哪一代、怎样工作。","initial":"ENIAC是早期第一代电子数字计算机。","actions":[{"label":"电子管机柜","stage":"第一代主要元件","result":"体积大、功耗高、发热明显。","tone":"good"},{"label":"十进制计数单元","stage":"不是典型二进制运算基础","result":"考试不要把后来的通用结构倒套给ENIAC。","tone":"warn"},{"label":"插线板与开关","stage":"最初不是存储程序方式","result":"更换任务需要人工重新接线和设置。","tone":"good"},{"label":"“已经采用存储程序”","stage":"错误","result":"存储程序思想在后续计算机中成为核心。","tone":"bad"}]},"y2026q1":{"kind":"choose","title":"识别错误的发展趋势","task":"考试给出若干趋势描述，点选后观察判断依据。","options":[{"label":"体积越大，速度越快","result":"错误。性能由工艺、体系结构、并行能力、存储等共同决定，体积不是必要条件。","tone":"bad"},{"label":"高性能与微型化并行发展","result":"正确。超级计算机追求规模，终端设备同时追求小型化和低功耗。","tone":"good"},{"label":"网络化、智能化不断增强","result":"正确。这是教材常见的计算机发展趋势概括。","tone":"good"}]},"y2020q31":{"kind":"sequence","title":"逐位完成二进制减法","task":"按运算顺序点击，演示1001₂−0111₂。","steps":[{"label":"右对齐数位","detail":"把1001与0111按最低位对齐。"},{"label":"最低位相减","detail":"1−1=0。"},{"label":"连续向高位借位","detail":"0不够减1时“借一当二”，并把借位继续传递。"},{"label":"写出结果并校验","detail":"得到0010₂，即10₂；用9−7=2复核。"}]},"y2020q23":{"kind":"explore","title":"看翻译层级辨语言","task":"点击三类语言，观察它们与CPU之间隔了什么。","initial":"越接近人类表达，通常越需要语言处理程序完成转换。","actions":[{"label":"机器语言","stage":"0101… → CPU","result":"由机器指令代码构成，可被CPU直接识别。","tone":"good"},{"label":"汇编语言","stage":"助记符 → 汇编器 → 机器指令","result":"用MOV等助记符表达，仍与机器结构关系紧密。","tone":"warn"},{"label":"高级语言","stage":"C/C++ → 编译或解释 → 机器执行","result":"更接近人的表达，但不能未经处理直接由CPU执行。","tone":"good"}]},"merged-2":{"kind":"explore","title":"把软件放进正确抽屉","task":"点击软件名称，观察分类依据是“主要功能”而不是“从哪里安装”。","initial":"系统软件提供运行环境；应用软件完成用户的具体任务。","actions":[{"label":"Windows 10","stage":"系统软件","result":"管理硬件、进程、文件并提供应用运行环境。","tone":"good"},{"label":"画图","stage":"应用软件","result":"虽然系统自带，但主要服务于绘图任务。","tone":"warn"},{"label":"Word 2016","stage":"应用软件","result":"直接完成文字处理任务。","tone":"good"},{"label":"语言处理程序","stage":"系统软件","result":"编译器、解释器通常归入系统软件。","tone":"good"}]},"y2024q41":{"kind":"explore","title":"把机器指令送进译码器","task":"点击指令的不同字段，观察控制器分别获得什么信息。","initial":"示例指令：ADD R1, [2048]。","actions":[{"label":"ADD","stage":"操作码","result":"告诉控制器执行加法。","tone":"good"},{"label":"R1","stage":"寄存器操作数","result":"指出一个数据位置。","tone":"good"},{"label":"2048","stage":"存储器地址","result":"指出另一个操作数的位置。","tone":"good"},{"label":"把地址当操作码","stage":"字段职责混淆","result":"地址回答“在哪里”，操作码回答“做什么”。","tone":"bad"}]},"y2026q31":{"kind":"explore","title":"把任务拖给合适的处理器","task":"用鼠标或手指把工作负载拖到CPU或GPU；放错会退回队列。","initial":"CPU和GPU分工协作，不是简单的替代关系。","actions":[{"label":"复杂分支与系统调度","stage":"CPU主导","result":"少量强核心与复杂控制逻辑更适合通用控制。","tone":"good"},{"label":"大规模矩阵并行","stage":"GPU加速","result":"大量相似计算可由众多计算单元并行完成。","tone":"good"},{"label":"运行整个操作系统","stage":"CPU主导，GPU协同","result":"GPU不具备全面替代通用CPU的条件。","tone":"warn"}]},"y2020q1":{"kind":"choose","title":"凭外形找出内存条","task":"题目常给硬件图片。点击最有辨识度的外形特征。","options":[{"label":"长条电路板＋成排金手指","result":"这是内存条的典型外形，安装在主板内存插槽中。","tone":"good"},{"label":"方形金属顶盖","result":"更像CPU封装，不是内存条。","tone":"bad"},{"label":"带RJ45网络接口","result":"更像网卡。","tone":"bad"},{"label":"布满插槽的大型电路板","result":"更像主板。","tone":"bad"}]},"y2020q22":{"kind":"explore","title":"沿数据方向判断设备","task":"点击设备，观察信息是进入、离开还是双向流动。","initial":"设备分类看主要功能，也要警惕磁盘等双向设备。","actions":[{"label":"手写板","stage":"人 → 计算机","result":"采集书写轨迹，属于输入设备。","tone":"good"},{"label":"麦克风","stage":"声音 → 计算机","result":"把声音转换为可处理的数据，属于输入设备。","tone":"good"},{"label":"投影仪","stage":"计算机 → 画面","result":"把结果呈现给人，属于输出设备。","tone":"good"},{"label":"硬盘","stage":"读取 ↔ 写入","result":"规范分类为外存，也具有输入输出双向性。","tone":"warn"}]},"y2025q1":{"kind":"explore","title":"调节CPU频率仪表","task":"点击参数，观察“3.20 GHz”真正描述什么。","initial":"CPU时钟：3.20 GHz。","actions":[{"label":"3.20 GHz","stage":"每秒约32亿个时钟周期","result":"这是频率，不是容量。","tone":"good"},{"label":"16 GB","stage":"内存容量","result":"GB用于计量存储容量。","tone":"warn"},{"label":"1 TB","stage":"硬盘容量","result":"不能把TB当作处理器速度。","tone":"warn"},{"label":"只看主频选最快CPU","stage":"证据不足","result":"架构、核心、缓存和负载同样重要。","tone":"bad"}]},"y2025q31":{"kind":"explore","title":"让SSD与HDD跑同一组任务","task":"点击工作负载，比较机械寻道和电子访问的差异。","initial":"两块盘都保存同一份文件。","actions":[{"label":"随机打开1000个小文件","stage":"SSD明显更快","result":"电子访问没有磁头寻道等待。","tone":"good"},{"label":"连续读取大文件","stage":"SSD通常更快","result":"实际速度还受接口和控制器限制。","tone":"good"},{"label":"受到剧烈震动","stage":"SSD更耐受","result":"HDD的机械结构更怕碰撞。","tone":"good"},{"label":"任何SSD都快于任何HDD","stage":"过度绝对","result":"设备等级与具体任务仍会影响结果。","tone":"bad"}]}};
